details.command:
kubectl patch deployment app -n default --patch '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "imagePullPolicy": "Always"
          }
        ]
      }
    }
  }
}'

cat << 'EOF' | kubectl patch deployment app -n default --type='merge' -
{"spec": {"template": {"spec": {"containers": [{"name": "app", "imagePullPolicy": "Always"}]}}}}
EOF
